import json
# find previous surveyor prompt in transcript
p='/home/siegfriedneto/.claude/projects/-home-siegfriedneto-projects-eternal/0213eba7-4325-47e3-ab5d-0c27c7fb7b7e.jsonl'
for line in open(p):
    d=json.loads(line)
    m=d.get('message',{})
    if isinstance(m.get('content'),list):
        for c in m['content']:
            if c.get('type')=='tool_use' and c.get('name')=='Agent' and 'domain-surveyor' in json.dumps(c['input']):
