P=~/.claude/plugins/cache/siegard-generator/siegard/4.28.0; WS=$(cat /tmp/chat/ws); python3 -B $P/bin/trace.py --reconciliation siegard-reconcile/adopt-chat.md 2>&1 | tee /tmp/chat/recon.txt; python3 -B $P/bin/trace.py --bind-record backend specification siegard-reconcile/adopt-chat.md --workspace $WS > /tmp/chat/bind.txt 2>&1; echo "exit $?"; tail -3 /tmp/chat/bind.txt; wc -l < /tmp/chat/bind.txt; python3 - <<'EOF'
import yaml,glob,collections
c=collections.Counter(); per=collections.defaultdict(list)
for f in glob.glob('siegard-reconcile/adopt-chat.returns/*.yaml'):
    d=yaml.safe_load(open(f))
    for x in d.get('findings') or []:
        c[x['kind']]+=1
        if x['kind']!='restates': per[x['kind']].append((f.split('__')[-1][:-5],x.get('node','-')))
print(c)
for k,v in per.items():
    print(k); [print('  ',a,b) for a,b in v]
EOF
grep -n -A6 'unheld' siegard-reconcile/adopt-chat.md | head -20
